import * as React from "react"
import { cn } from "@/lib/utils"

interface LedStripProps extends React.HTMLAttributes<HTMLDivElement> {
  colors?: string[]
  animated?: boolean
}

export function LedStrip({ 
  className, 
  colors = ["var(--accent-2)", "var(--accent)", "var(--led-cyan)", "var(--accent-2)"],
  animated = true,
  ...props 
}: LedStripProps) {
  return (
    <div className={cn("flex gap-2 items-center", className)} {...props}>
      {colors.map((color, i) => (
        <div
          key={i}
          className="w-2 h-2 rounded-full"
          style={{
            background: color,
            boxShadow: `0 0 8px ${color}`,
            animation: animated ? `rk-led 1.4s ease-in-out infinite ${i * 0.3}s` : undefined,
          }}
        />
      ))}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface RackBezelProps extends React.HTMLAttributes<HTMLDivElement> {
  label?: string
}

export function RackBezel({ 
  className, 
  label = "// MOCKUP · RACK_01",
  children,
  ...props 
}: RackBezelProps) {
  return (
    <div className={cn("relative", className)} {...props}>
      <div 
        className="flex items-center gap-2 px-4 py-2.5 border-b font-mono text-[10px] tracking-widest"
        style={{
          background: "var(--bg-2)",
          borderBottomColor: "var(--border-bright)",
          color: "var(--accent)",
        }}
      >
        <div 
          className="w-1.5 h-1.5 rounded-full"
          style={{
            background: "var(--accent-2)",
            boxShadow: "0 0 6px var(--accent-2)",
            animation: "rk-pulse 1.4s ease-in-out infinite",
          }}
        />
        {label}
      </div>
      {children}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface RackMockProps extends React.HTMLAttributes<HTMLDivElement> {
  children: React.ReactNode
}

export function RackMock({ className, children, ...props }: RackMockProps) {
  return (
    <div 
      className={cn(
        "relative z-10 w-[88%] flex flex-col gap-2 py-3.5 px-4",
        className
      )}
      style={{
        background: "#0a0a0c",
        border: "1px solid var(--border-bright)",
        borderRadius: "4px",
        minHeight: "220px",
      }}
      {...props}
    >
      {children}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

interface RackUnitProps extends React.HTMLAttributes<HTMLDivElement> {
  label: string
  ledColor?: string
  showScrews?: boolean
}

export function RackUnit({ 
  className, 
  label,
  ledColor = "var(--accent)",
  showScrews = true,
  ...props 
}: RackUnitProps) {
  return (
    <div 
      className={cn(
        "relative flex items-center justify-between px-4 min-h-[44px] font-mono text-sm",
        className
      )}
      style={{
        background: "linear-gradient(180deg, #1c1c20, #0a0a0c)",
        border: "1px solid var(--border)",
        borderRadius: "2px",
        boxShadow: "inset 0 1px 0 rgba(255, 255, 255, 0.03)",
      }}
      {...props}
    >
      {showScrews && (
        <>
          <div 
            className="absolute left-[-8px] top-1/2 -translate-y-1/2 w-1 h-1 rounded-full"
            style={{
              background: "radial-gradient(circle at 30% 30%, #5a5a63, #1a1a20)",
              boxShadow: "0 0 0 1px #0a0a0c",
            }}
          />
          <div 
            className="absolute right-[-8px] top-1/2 -translate-y-1/2 w-1 h-1 rounded-full"
            style={{
              background: "radial-gradient(circle at 30% 30%, #5a5a63, #1a1a20)",
              boxShadow: "0 0 0 1px #0a0a0c",
            }}
          />
        </>
      )}
      <span>{label}</span>
      <div 
        className="w-2 h-2 rounded-full"
        style={{
          background: ledColor,
          boxShadow: `0 0 8px ${ledColor}`,
          animation: "rk-led 1.4s ease-in-out infinite",
        }}
      />
    </div>
  )
}

/* Rack theme effects */
@keyframes rk-led {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

@keyframes rk-pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.6; transform: scale(0.95); }
}
